// Target path in BUZZ: desktop/scripts/check-route-tree.mjs  (NEW file)
//
// WHY THIS EXISTS
//
// `desktop/src/app/routeTree.gen.ts` is COMMITTED (it is tracked; `git
// ls-files` lists it) and is the only thing `desktop/src/app/router.tsx:3`
// imports. It is regenerated by the tanstackRouter vite plugin, configured at
// `desktop/vite.config.ts:11-23` with `virtualRouteConfig:
// "./src/app/routes.ts"`, which means the generator runs at dev-server start
// and at build — never in CI's typecheck or lint lanes.
//
// So a producer who edits `routes.ts` and commits without running a vite
// command ships a route that does not exist at runtime. `tsc --noEmit` passes
// (the generated tree is still valid TypeScript for the OLD route set), biome
// passes, and the first symptom is a blank surface behind a URL. Nothing in
// `just ci` catches it.
//
// This is a TEXT COMPARISON, not a build. It runs in milliseconds, needs no
// vite, no node_modules and no network. It is strictly weaker than
// regenerating and diffing — it cannot see a stale `validateSearch` or a
// changed component import — and strictly stronger than nothing, which is what
// exists today.
//
// WIRING (both halves, or it is decoration):
//   desktop/package.json "check:route-tree": "node ./scripts/check-route-tree.mjs"
//   desktop/package.json "check": "... && pnpm check:route-tree"
// `check` already chains `check:px-text` and `check:pubkey-truncation` the same
// way (desktop/package.json:15), and `just ci` runs `pnpm check`.
//
// EXIT CODES:  0 = in sync.  1 = drift (prints both sides).  2 = usage error.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// `--root` lets the gate be pointed at a checkout other than its own parent,
// which is how it is exercised from a test fixture. Default: desktop/.
const rootFlag = process.argv.indexOf("--root");
const projectRoot =
  rootFlag === -1
    ? path.resolve(__dirname, "..")
    : path.resolve(process.argv[rootFlag + 1] ?? "");

const declaredPath = path.join(projectRoot, "src/app/routes.ts");
const generatedPath = path.join(projectRoot, "src/app/routeTree.gen.ts");

for (const file of [declaredPath, generatedPath]) {
  if (!fs.existsSync(file)) {
    console.error(
      `check-route-tree: missing ${path.relative(projectRoot, file)}`,
    );
    process.exit(2);
  }
}

const declaredSource = fs.readFileSync(declaredPath, "utf8");
const generatedSource = fs.readFileSync(generatedPath, "utf8");

/**
 * Paths declared in routes.ts.
 *
 * `index("…")` declares "/" and carries no path literal of its own, so it is
 * matched separately. `route("/x", "x.tsx")` declares its first argument.
 * Prettier/biome may wrap a long `route(` across lines, so the newline is
 * matched explicitly rather than assumed away.
 */
function declaredRoutePaths(source) {
  const found = new Set();
  if (/\bindex\(\s*["'][^"']+["']\s*\)/.test(source)) found.add("/");
  const routeRe = /\broute\(\s*\n?\s*["']([^"']+)["']/g;
  for (const match of source.matchAll(routeRe)) found.add(match[1]);
  return found;
}

/**
 * Paths present in routeTree.gen.ts.
 *
 * The generator emits each path twice — once in the `.update({ id, path })`
 * call and once in the `declare module` interface — so the Set dedupes. The
 * root route emits `id: "__root__"` with no `path`, which is why only `path:`
 * is read. Quote style follows whatever formatter last touched the file, so
 * both are accepted.
 */
function generatedRoutePaths(source) {
  const found = new Set();
  const pathRe = /\bpath:\s*["']([^"']+)["']/g;
  for (const match of source.matchAll(pathRe)) found.add(match[1]);
  return found;
}

const declared = declaredRoutePaths(declaredSource);
const generated = generatedRoutePaths(generatedSource);

if (declared.size === 0) {
  console.error(
    "check-route-tree: parsed zero routes from src/app/routes.ts.\n" +
      "  A gate that scans nothing passes everything. Fix the parser, not the tree.",
  );
  process.exit(2);
}

const missingFromTree = [...declared].filter((p) => !generated.has(p)).sort();
const extraInTree = [...generated].filter((p) => !declared.has(p)).sort();

if (missingFromTree.length === 0 && extraInTree.length === 0) {
  console.log(
    `check-route-tree: ${declared.size} route paths in sync between src/app/routes.ts and src/app/routeTree.gen.ts`,
  );
  process.exit(0);
}

console.error(
  "check-route-tree: routeTree.gen.ts is out of sync with routes.ts.\n",
);
for (const p of missingFromTree) {
  console.error(`  declared in routes.ts, absent from routeTree.gen.ts:  ${p}`);
}
for (const p of extraInTree) {
  console.error(`  present in routeTree.gen.ts, absent from routes.ts:   ${p}`);
}
console.error(
  "\n  Fix: run any vite command in desktop/ (`pnpm dev` or `pnpm build`) to" +
    "\n  regenerate the tree, then commit src/app/routeTree.gen.ts with your change.",
);
process.exit(1);
